insert into public.workspaces(id,name) values ('00000000-0000-4000-8000-000000000001','RevenueOS Demo') on conflict do nothing;
insert into public.agents(id,workspace_id,name,mandate,status,generation,budget,spent,revenue,survival_score,thesis,last_heartbeat_at)
insert into public.opportunities(id,workspace_id,agent_id,title,segment,stage,value,probability,confidence,effort,risk,summary)
insert into public.experiments(opportunity_id,name,status,metric,target,progress,spend) select ('20000000-0000-4000-8000-'||lpad(((n-1)%24+1)::text,12,'0'))::uuid,'Experiment '||n,(array['queued','running','paused','complete']::public.experiment_status[])[n%4+1],'Pipeline created','> $40,000',(n*7)%100,n*300 from generate_series(1,16)n;
insert into public.knowledge(workspace_id,title,body,source,tag,confidence) select '00000000-0000-4000-8000-000000000001','Insight '||n,'Seeded knowledge preserves source and confidence.','Product telemetry',(array['Signal','Buyer','Channel','Pricing'])[n%4+1],.5+(n%5)*.08 from generate_series(1,12)n;
insert into public.transactions(workspace_id,description,category,amount,direction,status) select '00000000-0000-4000-8000-000000000001','Ledger entry '||n,'Growth',n*1250,case when n%3=0 then 'out'::public.transaction_direction else 'in'::public.transaction_direction end,case when n%5=0 then 'pending'::public.transaction_status else 'posted'::public.transaction_status end from generate_series(1,18)n;
insert into public.events(workspace_id,actor,event_type,detail) select '00000000-0000-4000-8000-000000000001','Agent '||n,'seed_event',jsonb_build_object('message','Traceable seeded event') from generate_series(1,16)n;
insert into public.agent_rules(workspace_id,name,config) values ('00000000-0000-4000-8000-000000000001','spend_cap',jsonb_build_object('per_agent_daily',2500,'approval_threshold',1000)),('00000000-0000-4000-8000-000000000001','survival_review',jsonb_build_object('min_score',30,'human_decision_required',true));
