-- Deterministic development seed; no auth user or secrets required.
select ('10000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-4000-8000-000000000001','Agent '||n,'Discover and validate a revenue motion',case when n<=12 then 'active'::public.agent_status when n<=17 then 'paused'::public.agent_status else 'dead'::public.agent_status end,1,12000,700*n,2500*n,greatest(8,95-n*3),'Evidence before scale',now()-((n%8)||' hours')::interval from generate_series(1,27) n on conflict do nothing;
select ('20000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-4000-8000-000000000001',('10000000-0000-4000-8000-'||lpad(((n-1)%12+1)::text,12,'0'))::uuid,'Revenue motion '||n,case when n%3=0 then 'Enterprise' else 'Mid-market' end,(array['signal','qualified','experimenting','committed','won','lost']::public.opportunity_stage[])[(n-1)%6+1],15000+n*6000,.25+(n%6)*.1,.45+(n%5)*.1,1+n%6,(array['low','medium','high'])[n%3+1],'Seeded evidence-backed opportunity' from generate_series(1,24)n on conflict do nothing;
